def choose_oranges():
    n = 10  # total number of oranges
    r = 2   # number of oranges to choose

    # Calculate the factorial of a number
    def factorial(x):
        if x == 0 or x == 1:
            return 1
        else:
            return x * factorial(x - 1)

    # Calculate combinations using the formula C(n, r) = n! / (r! * (n-r)!)
    combinations = factorial(n) // (factorial(r) * factorial(n - r))

    return combinations

answer = choose_oranges()
